CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS app_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('engineer','supervisor','admin')), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS locations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS meters (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, utility_type TEXT NOT NULL CHECK(utility_type IN ('electricity','water','gas','other')), location_id UUID REFERENCES locations(id), unit TEXT NOT NULL, multiplier NUMERIC(20,8) NOT NULL DEFAULT 1 CHECK(multiplier > 0), supplier_name TEXT, baseline_reading NUMERIC(20,6), rollover_value NUMERIC(20,6), is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS utility_rates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), meter_id UUID REFERENCES meters(id), utility_type TEXT, unit TEXT NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'IDR', rate_per_unit NUMERIC(20,6) NOT NULL CHECK(rate_per_unit >= 0), effective_from DATE NOT NULL, effective_to DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(effective_to IS NULL OR effective_to >= effective_from));
CREATE TABLE IF NOT EXISTS meter_readings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), meter_id UUID NOT NULL REFERENCES meters(id), reading_date DATE NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(), recorded_by UUID REFERENCES app_users(id), photo_storage_key TEXT NOT NULL, photo_sha256 CHAR(64) NOT NULL, ocr_reading NUMERIC(20,6), ocr_confidence NUMERIC(6,5), verified_reading NUMERIC(20,6) NOT NULL CHECK(verified_reading >= 0), previous_reading NUMERIC(20,6), multiplier_snapshot NUMERIC(20,8) NOT NULL, rate_id UUID REFERENCES utility_rates(id), rate_snapshot NUMERIC(20,6), currency CHAR(3), consumption NUMERIC(20,6), estimated_cost NUMERIC(20,2), status TEXT NOT NULL DEFAULT 'pending_review' CHECK(status IN ('pending_review','verified','rejected','baseline','requires_review')), correction_reason TEXT, verified_by UUID REFERENCES app_users(id), verified_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(meter_id, reading_date));
CREATE INDEX IF NOT EXISTS meter_readings_date_idx ON meter_readings(reading_date DESC);
CREATE TABLE IF NOT EXISTS shifts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, start_time TIME NOT NULL, end_time TIME NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS checklist_templates (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(name,version));
CREATE TABLE IF NOT EXISTS checklist_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), template_id UUID NOT NULL REFERENCES checklist_templates(id), area TEXT NOT NULL, equipment TEXT NOT NULL, label TEXT NOT NULL, input_type TEXT NOT NULL CHECK(input_type IN ('numeric','text','boolean','select','status','photo')), unit TEXT, min_value NUMERIC(20,6), max_value NUMERIC(20,6), is_required BOOLEAN NOT NULL DEFAULT TRUE, instructions TEXT, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS checklist_submissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), template_id UUID NOT NULL REFERENCES checklist_templates(id), shift_id UUID NOT NULL REFERENCES shifts(id), shift_date DATE NOT NULL, submitted_by UUID NOT NULL REFERENCES app_users(id), submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), status TEXT NOT NULL DEFAULT 'submitted', reviewed_by UUID REFERENCES app_users(id), reviewed_at TIMESTAMPTZ, UNIQUE(template_id,shift_id,shift_date));
CREATE TABLE IF NOT EXISTS checklist_responses (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), submission_id UUID NOT NULL REFERENCES checklist_submissions(id), item_id UUID NOT NULL REFERENCES checklist_items(id), numeric_value NUMERIC(20,6), text_value TEXT, boolean_value BOOLEAN, status_value TEXT, photo_storage_key TEXT, remarks TEXT, finding TEXT, corrective_action TEXT, UNIQUE(submission_id,item_id));
CREATE TABLE IF NOT EXISTS suppliers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, contact_info JSONB NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS budgets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, version INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'draft', currency CHAR(3) NOT NULL DEFAULT 'IDR', created_by UUID REFERENCES app_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(period_end >= period_start), UNIQUE(name,period_start,period_end,version));
CREATE TABLE IF NOT EXISTS budget_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), budget_id UUID NOT NULL REFERENCES budgets(id), meter_id UUID REFERENCES meters(id), utility_type TEXT NOT NULL, target_quantity NUMERIC(20,6), target_amount NUMERIC(20,2) NOT NULL CHECK(target_amount >= 0), unit TEXT, area TEXT);
CREATE TABLE IF NOT EXISTS documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id UUID REFERENCES suppliers(id), document_type TEXT NOT NULL, original_name TEXT NOT NULL, storage_key TEXT NOT NULL, sha256 CHAR(64) NOT NULL, mime_type TEXT NOT NULL, size_bytes BIGINT NOT NULL CHECK(size_bytes > 0), uploaded_by UUID REFERENCES app_users(id), uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(), extraction_status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_id UUID NOT NULL UNIQUE REFERENCES documents(id), supplier_id UUID REFERENCES suppliers(id), invoice_number TEXT, invoice_date DATE, service_period_start DATE, service_period_end DATE, due_date DATE, currency CHAR(3) NOT NULL DEFAULT 'IDR', subtotal NUMERIC(20,2), tax_amount NUMERIC(20,2), fixed_charges NUMERIC(20,2), adjustments NUMERIC(20,2), total_amount NUMERIC(20,2), reviewed_values JSONB NOT NULL DEFAULT '{}', status TEXT NOT NULL DEFAULT 'pending_review', reviewed_by UUID REFERENCES app_users(id), reviewed_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS invoices_supplier_number_unique ON invoices(supplier_id,invoice_number) WHERE invoice_number IS NOT NULL;
CREATE TABLE IF NOT EXISTS invoice_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id UUID NOT NULL REFERENCES invoices(id), description TEXT NOT NULL, quantity NUMERIC(20,6), unit TEXT, rate NUMERIC(20,6), amount NUMERIC(20,2), meter_id UUID REFERENCES meters(id), line_type TEXT NOT NULL DEFAULT 'utility');
CREATE TABLE IF NOT EXISTS invoice_payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id UUID NOT NULL REFERENCES invoices(id), paid_at DATE NOT NULL, amount NUMERIC(20,2) NOT NULL CHECK(amount > 0), reference TEXT, notes TEXT, recorded_by UUID REFERENCES app_users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id BIGSERIAL PRIMARY KEY, actor_id UUID REFERENCES app_users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT, before_data JSONB, after_data JSONB, ip_address INET, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_logs_entity_idx ON audit_logs(entity_type,entity_id,created_at DESC);
